import { CountryGuide, LocalizedText } from '../types/voyago';
import { VOYAGO_IMAGES } from './featuredCountries';

interface WorldSeed {
  id: string;
  code: string;
  flag: string;
  continent: 'americas' | 'asia' | 'oceania';
  subregion: LocalizedText;
  name: LocalizedText;
  capital: LocalizedText;
  cities: string[];
  monument: LocalizedText;
  era: string;
  dish: LocalizedText;
  currencyCode: string;
  currencySymbol: string;
  currencyName: LocalizedText;
  image?: string;
}

function defaultImageFor(seed: WorldSeed): string {
  if (seed.image) return seed.image;
  if (seed.continent === 'oceania') return VOYAGO_IMAGES.sydneyOpera;
  if (seed.continent === 'asia') {
    if (seed.id === 'japan' || seed.id === 'south-korea' || seed.id === 'taiwan') {
      return VOYAGO_IMAGES.japan;
    }
    if (seed.id === 'china' || seed.id === 'mongolia') {
      return VOYAGO_IMAGES.china;
    }
    const arRegion = seed.subregion.en.toLowerCase();
    if (arRegion.includes('middle east') || arRegion.includes('west asia')) {
      return VOYAGO_IMAGES.morocco;
    }
    return VOYAGO_IMAGES.tajMahal;
  }
  // Americas
  if (seed.subregion.en.includes('South America')) {
    return seed.id === 'uruguay' || seed.id === 'chile' || seed.id === 'paraguay'
      ? VOYAGO_IMAGES.buenosAires
      : VOYAGO_IMAGES.christRedeemer;
  }
  return VOYAGO_IMAGES.statueLiberty;
}

function buildWorldCountry(seed: WorldSeed): CountryGuide {
  const image = defaultImageFor(seed);
  return {
    id: seed.id,
    code: seed.code,
    flag: seed.flag,
    continent: seed.continent,
    subregion: seed.subregion,
    name: seed.name,
    capital: seed.capital,
    bestSeason: {
      en: 'Dry & Mild Season (Check local climate)',
      fr: 'Saison sèche et douce idéale',
      ar: 'الموسم المعتدل والجاف',
    },
    summary: {
      en: `Explore ${seed.name.en} from ${seed.capital.en} to ${seed.cities.slice(0, 2).join(' and ')}, featuring ${seed.monument.en}, traditional ${seed.dish.en}, and travel tips in ${seed.currencyCode}.`,
      fr: `Découvrez ${seed.name.fr} de ${seed.capital.fr} à ${seed.cities.slice(0, 2).join(' et ')}, avec ${seed.monument.fr}, la gastronomie ${seed.dish.fr} et conseils en ${seed.currencyCode}.`,
      ar: `استكشف ${seed.name.ar} من ${seed.capital.ar} مع زيارة ${seed.monument.ar} وتذوق ${seed.dish.ar} ومعلومات العملة (${seed.currencyCode}).`,
    },
    wifiTips: {
      en: `Airport tourist SIMs and eSIMs provide reliable 4G/5G data in ${seed.capital.en}; hotels and cafés include Wi-Fi.`,
      fr: `Cartes SIM touristiques et eSIM disponibles à ${seed.capital.fr} ; Wi-Fi dans la plupart des hôtels.`,
      ar: `تتوفر شرائح الاتصال وeSIM في مطار ${seed.capital.ar}، كما يتوفر Wi-Fi في الفنادق والمقاهي.`,
    },
    heroImage: image,
    mapsQuery: `${seed.name.en} ${seed.capital.en} attractions`,
    currency: {
      code: seed.currencyCode,
      symbol: seed.currencySymbol,
      name: seed.currencyName,
      tips: {
        en: `Carry ${seed.currencyCode} cash for local markets and transit; major hotels and city restaurants accept international cards.`,
        fr: `Prévoyez du ${seed.currencyCode} en espèces pour les marchés ; cartes acceptées dans les grands hôtels et restaurants.`,
        ar: `يُفضل حمل عملة ${seed.currencyCode} نقداً للأسواق والمواصلات، وتُقبل البطاقات في الفنادق الكبرى.`,
      },
    },
    cities: seed.cities.map((c) => ({
      name: { en: c, fr: c, ar: c },
      highlight: {
        en: `Historic neighborhoods, museums, and local culinary markets in ${c}.`,
        fr: `Quartiers historiques, musées et marchés culinaires à ${c}.`,
        ar: `الأحياء التاريخية والمتاحف والأسواق الشعبية في ${c}.`,
      },
      mapsQuery: `${c}, ${seed.name.en}`,
    })),
    monuments: [
      {
        id: `${seed.id}-monument-1`,
        name: seed.monument,
        city: seed.cities[0] || seed.capital.en,
        era: seed.era,
        description: {
          en: `${seed.monument.en} is a renowned historical and architectural landmark representing the heritage of ${seed.name.en}.`,
          fr: `${seed.monument.fr} est un monument historique majeur qui incarne le patrimoine de ${seed.name.fr}.`,
          ar: `يُعد ${seed.monument.ar} من أشهر المعالم التاريخية والمعمارية التي تجسد تراث ${seed.name.ar}.`,
        },
        image,
        mapsQuery: `${seed.monument.en} ${seed.name.en}`,
      },
    ],
    dishes: [
      {
        name: seed.dish,
        category: { en: 'National Specialty', fr: 'Spécialité nationale', ar: 'طبق تقليدي' },
        description: {
          en: `Beloved traditional dish of ${seed.name.en} prepared with authentic regional ingredients and spices.`,
          fr: `Plat emblématique de ${seed.name.fr} préparé selon les recettes traditionnelles locales.`,
          ar: `أحد أشهر الأطباق الوطنية في ${seed.name.ar} بنكهاته وتوابله المحلية الأصيلة.`,
        },
      },
    ],
    phrases: [
      { label: { en: 'Hello', fr: 'Bonjour', ar: 'مرحباً' }, local: 'Hello', pronunciation: 'Local greeting' },
      { label: { en: 'Thank you', fr: 'Merci', ar: 'شكراً' }, local: 'Thank you', pronunciation: 'Polite thanks' },
    ],
  };
}

